  if(primary.hp>0&&!skill){if(player.job==='sage'&&classBuffs.autoSpell?.until>now&&Math.random()<classBuffs.autoSpell.power){const bonus=dealDamage(hitDamage(stat('matk')*.8,Math.floor(primary.def*.25)),'playerDamage');message(`自動念咒追加 ${bonus} 魔法傷害！`,'good');emitEvent('autospell');}if(player.job==='hunter'&&Math.random()<passiveBonus('falcon')){const bonus=dealDamage(hitDamage(stat('atk')*.35,primary.def*.5),'playerDamage');message(`獵鷹協攻造成 ${bonus} 傷害！`,'good');emitEvent('falcon');}if(player.job==='monk'){timers.combo=(timers.combo||0)+1;if(timers.combo%3===0){dealDamage(hitDamage(stat('atk')*.65,primary.def),'playerDamage');emitEvent('combo');}}}
