function reportMetrics(r){const contribution=combatContribution(r.metrics);const owner=(r.metrics.playerDamage||0)+(r.metrics.playerBuffDamage||0),pet=(r.metrics.petDamage||0)+(r.metrics.resonanceDamage||0)+(r.metrics.buffDamage||0),total=owner+pet;return `${r.scoringVersion===24?'':'<div class="report-notice">舊版戰報：缺少新版防禦與增益歸屬資料，保留原始紀錄，不納入新版總貢獻比較。</div>'}<div class="report-notice">${r.scoringVersion===24&&contribution.total?`戰鬥貢獻參考值：人物 ${(contribution.ownerShare*100).toFixed(1)}%／寵物 ${((1-contribution.ownerShare)*100).toFixed(1)}%<br>`:''}${total?`傷害來源：人物 ${(owner/total*100).toFixed(1)}%／寵物 ${(pet/total*100).toFixed(1)}%`:'尚無傷害資料'}；參考評分以傷害、有效治療、實際吸收護盾、實際承傷與防禦減傷的 HP 等值計算。重複的受傷紀錄與攔截估算不再加分，SP 及打斷次數另列；比例會隨敵人與隊伍需求變動，不代表固定戰力。</div>`+`<div class="report-grid">${FIELDS.map(key=>`<div class="report-metric"><small>${NAMES[key]}</small><strong>${Math.round(r.metrics[key]||0).toLocaleString('zh-TW')}</strong></div>`).join('')}</div>`;}
function reportName(r){return `${SPECIES[r.monster]?.name||'未知敵人'} · ${r.petName||'未出戰'}`;}
function renderReports(){const history=player.battleHistory||[];let html='<div class="item"><b>有效戰鬥貢獻</b><p>總評分包含實際傷害、未溢補治療、實際吸收護盾、實際承傷與防禦減傷。攻擊、魔法寵偏重輸出；防禦、輔助寵偏重保護與續航。每項均以 HP 等值計分並依來源歸屬；SP另列，不重複計算估算項目。</p></div>';if(report){html+=`<div class="report-card"><div class="report-title"><b>● 本場進行中</b><span class="pill">${escapeHtml(reportName(report))}</span></div>${reportMetrics(report)}</div>`;}else html+='<p class="muted">目前沒有進行中的戰鬥。</p>';html+='<div class="report-notice">BUFF 額外傷害包含寵物自主祝福與元素印記提供的實際額外傷害；控制、打斷仍待未來技能實裝。防禦寵物攔截值依敵方攻擊與玩家防禦估算，非實際承傷；護盾僅記錄已吸收部分。戰報保留最近 12 場並隨角色存檔。</div><h2 style="margin-top:16px">最近戰報</h2>';html+=history.length?`<div class="report-history">${history.slice().reverse().map(r=>`<details><summary><b>${escapeHtml(r.outcome)}</b> · ${escapeHtml(reportName(r))} · ${Math.max(0,Math.round(((r.endedAt||r.startedAt)-r.startedAt)/1000))} 秒</summary>${reportMetrics(r)}</details>`).join('')}</div>`:'<div class="empty">還沒有已結束的戰鬥。打倒一隻怪物後即可查看報告。</div>';return html;}
function renderPetSkillConfig(){const pet=activePet();if(!pet)return '<div class="item">先選擇一隻出戰寵物，再配置牠的技能與裝備。</div>';const role=SPECIES[pet.species].role;return `<div class="item"><b>${escapeHtml(pet.nickname)} · 三部位裝備</b><p>寵物裝備可強化 ATK、MATK、HP、DEF、HIT、FLEE 與 ASPD，魔法型以 MATK 計算傷害。</p>${Object.entries(PET_SLOTS).map(([slot,name])=>{const g=pet.gear?.[slot];return `<div class="skill-option"><b>${name}：${g?escapeHtml(g.name):'未裝備'}</b>${g?`<small>${gearLabel(g)} · ${Object.entries(g.affixes||{}).map(([k,v])=>affixLabel(k,v)).join('、')}</small><button data-petoff="${slot}">卸下</button>`:''}</div>`}).join('')}</div><div class="item"><b>${escapeHtml(pet.nickname)} · 自動技能配置</b><p>${petAbilitySetName(pet.rarity)} · 每組6招，隨寵物等級解鎖，可裝備2招。普通→稀有→罕見各強化6%；傳說與神話各再強化12.5%。技能自動施放會消耗寵物 SP。下方預估依目前寵物能力（含裝備）計算；實際回復依缺額、主人與夥伴護盾各以自身最大HP的25%為上限，護盾6.5秒後消退；守護護盾優先保護夥伴。增益以施放當下能力決定。</p>${petSkillsFor(role,pet.rarity).map(s=>{const equipped=(pet.equippedSkills||[]).includes(s.id),unlocked=pet.level>=s.unlock;return `<div class="skill-option"><b>${s.name}</b><small>${s.description}<br>${petSkillPreview(s,petStats(pet),role)} · SP ${6+s.unlock*2} · ${Math.round(s.cooldown/1000)}秒冷卻 · Lv.${s.unlock}</small><button data-petskill="${pet.id}:${s.id}" ${unlocked?'':'disabled'}>${equipped?'卸下':unlocked?'裝備':'未解鎖'}</button></div>`}).join('')}</div>`;}
function renderTransfer(){if(SECOND_JOBS[player.job])return `<div class="item"><b>${CLASSES[player.job].name} · 二轉已完成</b><p>${SECOND_JOBS[player.job].style} · ${rangeLabel(playerRange(player.job))}<br>一轉Job ${player.firstJobLevel} · 一轉剩餘點數 ${player.firstJobPoints||0} · 二轉剩餘點數 ${player.jobPoints}</p></div>`;return `<div class="item"><b>城鎮二轉公會</b><p>需求 Base Lv.50、Job Lv.40。保留一轉技能與剩餘點數，二轉Job重設為1。贈送星輝罕見職業武器並換裝，原裝備／卡片退回背包。</p>${secondJobChoices(player.job).map(([id,meta])=>`<div class="transfer-option">${spriteHtml(id,'choice')}<b>${meta.name} · ${rangeLabel(meta.range)}</b><p>${meta.style}</p><button data-transfer="${id}" ${transferEligibility(player,id)?'disabled':''}>${transferEligibility(player,id)||'轉職為'+meta.name}</button></div>`).join('')}</div>`;}
function transferJob(target){const error=transferEligibility(player,target);if(error)return toast(error);const meta=SECOND_JOBS[target];if(!confirm(`確定二轉為「${meta.name}」？\n保留一轉技能；Job重設為1，原裝備與卡片退回，獲得罕見職業武器。`))return;player.firstJobLevel=player.jobLevel;player.firstJobPoints=player.jobPoints;player.job=target;player.jobLevel=1;player.jobXp=0;player.jobPoints=0;const starter=rollGear(meta.weapon,Math.min(50,player.level),'uncommon');stowEquipped('rightHand');stowEquipped('leftHand');player.gear.rightHand=starter;const learned=activeJobSkills(target).find(s=>s.branch==='second');player.jobSkills[learned.id]=1;player.equippedJobSkill=learned.id;player.hp=stat('hp');player.mp=stat('mp');classBuffs={};jobSkillTimers={};timers.resonance=0;dirty=true;save();message(`二轉成功！現在是【${meta.name}】。`,'rare');render();}
function renderJobTree(){return `<div class="item"><b>金幣重新訓練</b><p>每次 ${retrainCost(player.level)} 金，屬性與一／二轉技能點完整退回對應點數池。</p><button data-retrain="attributes">重置屬性</button> <button data-retrain="skills">重置技能</button></div>`+renderTransfer()+`<div class="item"><b>${CLASSES[player.job].name} · 主動與被動技能</b><p>Job 屬性加成：${Object.entries(jobAttributeBonus(player,SECOND_JOBS)).map(([key,value])=>`${key} +${value}`).join(' · ')}<br>Job Level 成長會逐步取得本職業加成，二轉保留一轉加成。</p><p>Base上限99、Job上限50。一轉與二轉點數分別保留。主動技能顯示倍率、SP與CD，被動學習後常駐生效；每招共用0.85秒施放間隔。</p>${['second','first'].filter(branch=>JOB_SKILLS[player.job].some(s=>s.branch===branch)).map(branch=>`<section class="job-skill-section ${branch}"><h3>${branch==='second'?'二轉專屬技能':'一轉基礎技能'} · 可用 ${branch==='first'&&SECOND_JOBS[player.job]?player.firstJobPoints:player.jobPoints} 點</h3>${JOB_SKILLS[player.job].filter(s=>s.branch===branch).map(s=>{const rank=player.jobSkills[s.id]||0,first=s.branch==='first'&&SECOND_JOBS[player.job],points=first?player.firstJobPoints:player.jobPoints,unlocked=skillUnlocked(player,s),passive=s.kind==='passive';return `<div class="skill-option"><b>${passive?'◆ 被動':'✦ 主動'} ${s.name} <span class="pill">Lv.${rank}/${s.maxRank}</span></b><small>${first?'一轉基礎 · ':s.branch==='second'?'二轉專屬 · ':''}${s.desc}<br>${jobSkillSpec(s,Math.max(1,rank),player.job).text}${s.aoe?` · 同時攻擊最多${s.targets||3}個目標，每個目標獨立承受上述倍率`:''} · Job ${s.unlock}${passive?'':` · SP ${s.mp}`}<br>${s.weapons.length?'武器：'+s.weapons.map(w=>({sword:'單手劍',greatsword:'雙手劍',spear:'單手槍',greatspear:'雙手槍',dual:'雙短劍',dagger:'短劍',katar:'拳刃',staff:'單手杖',greatstaff:'雙手杖',mace:'單手權杖',spellfist:'魔拳套',knuckle:'拳套',instrument:'樂器',bow:'弓'})[w]||w).join('／'):'不限武器'}${!passive&&!canCastJobSkill(s)?' · 目前武器不符':''}</small><div class="skill-actions"><button data-jobup="${s.id}" ${unlocked&&points>0&&rank<s.maxRank?'':'disabled'}>升級技能</button>${passive?'':`<button data-jobequip="${s.id}" ${rank&&player.equippedJobSkill!==s.id?'':'disabled'}>${player.equippedJobSkill===s.id?'預設技能':'設為預設'}</button>`}</div></div>`;}).join('')}</section>`).join('')}</div>`;}
function evolvePet(id){const pet=player.pets.find(p=>p.id===id),step=pet&&nextPetEvolution(pet);if(!pet||!step)return toast('寵物已達進化上限');if(player.location!=='town')return toast('只能在城鎮進化');if(pet.level<step.level)return toast(`需寵物 Lv.${step.level}`);if((player.bag.find(e=>e.id===step.id)?.qty||0)<step.count)return toast('進化素材不足');evolutionPreview={id,before:JSON.parse(JSON.stringify(pet))};$('evolutionModal').style.display='grid';$('gameShell').inert=true;$('evolutionScene').className='evolution-scene preview';$('evolutionBefore').src=petArt(pet);$('evolutionAfter').src=petArt(pet,evolutionStage(pet)+1);$('evolutionTitle').textContent='夥伴即將迎來新的形態';$('evolutionStatus').textContent=`${petForm(pet)} → 下一階形態 · 消耗 ${ITEMS[step.id].name} ×${step.count}`;$('evolutionStart').hidden=false;$('evolutionStart').disabled=false;$('evolutionClose').disabled=false;$('evolutionClose').textContent='取消';$('evolutionStart').focus();}
function beginEvolution(){if(evolutionRunning||!evolutionPreview)return;const pet=player.pets.find(p=>p.id===evolutionPreview.id);if(!pet)return closeEvolution();const before=JSON.parse(JSON.stringify(pet)),bagBefore=JSON.parse(JSON.stringify(player.bag)),result=evolveCompanion(pet,player.bag,player.location,PET_EVOLUTIONS,PET_RARITIES);if(result.error)return toast(result.error);migratePetSkills(pet,SPECIES[pet.species].role);pet.hp=petStats(pet).hp;pet.sp=petStats(pet).sp;if(activePet()?.id===pet.id)clearPetEffects();dirty=true;if(save()===false){Object.assign(pet,before);player.bag=bagBefore;return toast('存檔失敗，本次進化未扣除素材');}stopAutoFusion('寵物進化中');evolutionRunning=true;$('evolutionAfter').src=petArt(pet);$('evolutionScene').className='evolution-scene evolving';$('evolutionTitle').textContent='進化之光正在凝聚…';$('evolutionStatus').textContent='夥伴的輪廓正在變化，請稍候…';$('evolutionStart').hidden=true;$('evolutionClose').disabled=true;evolutionTimer=setTimeout(()=>{evolutionRunning=false;const mutation=result.before!==result.after&&['legendary','mythic'].includes(result.after);$('evolutionScene').className='evolution-scene complete';$('evolutionTitle').textContent=mutation?`太驚人了，居然是【${result.form}】！`:`恭喜您，進化為【${result.form}】！`;$('evolutionStatus').textContent=`${petRarity(pet).name} · ${petAbilitySetName(pet.rarity)}${result.before!==result.after?' · 品質提升成功':''}`;$('evolutionClose').disabled=false;$('evolutionClose').textContent='繼續冒險';$('evolutionClose').focus();message($('evolutionTitle').textContent,'rare');render();},4000);}
