function renderEntry(){const slots=lobbySlots();$('slotGrid').innerHTML=slots.map(({index,player:p,error})=>`<article class="slot-card ${selectedSlot===index?'selected':''} ${p?'occupied':'empty'}"><button class="slot-select" data-slot-select="${index}" aria-label="選擇第 ${index+1} 格${p?' '+escapeHtml(p.name):' 空白角色'}"><span class="slot-number">CHARACTER 0${index+1}</span>${p?spriteHtml(p.job,'entry'):'<span class="slot-empty-art">＋</span>'}<h2>${p?escapeHtml(p.name):error?'存檔待還原':'尚未建立角色'}</h2><p>${p?`${CLASSES[p.job].name} · ${rangeLabel(playerRange(p.job))}`:error||'建立一位新的冒險者'}</p>${p?`<div class="slot-levels"><span>BLV <b>${p.level}</b></span><span>JLV <b>${p.jobLevel}</b></span><span>寵物 <b>${p.pets.length}</b></span></div><small>${MAPS[p.location]?.name||'寵物之地'} · 金幣 ${Number(p.gold).toLocaleString('zh-TW')}</small>`:'<small>獨立角色、背包、寵物與進度</small>'}</button><div class="slot-actions"><button data-slot-new="${index}" aria-label="第 ${index+1} 格新建或覆蓋">${p||error?'新建覆蓋':'建立角色'}</button><button data-slot-import="${index}" aria-label="第 ${index+1} 格導入存檔">導入</button><button data-slot-export="${index}" aria-label="第 ${index+1} 格匯出存檔" ${p?'':'disabled'}>匯出</button></div></article>`).join('');const selected=slots[selectedSlot];$('enterGameBtn').disabled=!selected?.player;$('enterGameBtn').textContent=selected?.player?`進入遊戲 · ${selected.player.name}`:'請先建立或導入角色';$('entrySelection').textContent=`目前選擇第 ${selectedSlot+1} 格 · ${selected?.player?.name||'空白存檔'}`;for(const button of $('slotGrid').querySelectorAll('[data-slot-select]'))button.onclick=()=>{selectedSlot=Number(button.dataset.slotSelect);renderEntry()};for(const button of $('slotGrid').querySelectorAll('[data-slot-new]'))button.onclick=()=>openCharacterCreation(Number(button.dataset.slotNew));for(const button of $('slotGrid').querySelectorAll('[data-slot-import]'))button.onclick=()=>{importTargetSlot=Number(button.dataset.slotImport);$('saveFile').click()};for(const button of $('slotGrid').querySelectorAll('[data-slot-export]'))button.onclick=()=>exportCharacterSlot(Number(button.dataset.slotExport));}
