function retrain(kind){
 if(player.location!=='town')return toast('請回城鎮重新訓練');const cost=retrainCost(player.level);if(player.gold<cost)return toast(`需要 ${cost} 金`);
 if(!confirm(`花費 ${cost} 金重置${kind==='attributes'?'屬性':'一轉與二轉技能'}？已使用點數會完整退回。`))return;
 const previous=structuredClone(player);player.gold-=cost;
 if(kind==='attributes'){for(const key of Object.keys(ATTRS)){player.statPoints+=Math.max(0,player.attributes[key]-1);player.attributes[key]=1;}}
 else{for(const branch of ['first','second']){const skills=JOB_SKILLS[player.job].filter(s=>s.branch===branch);if(!skills.length)continue;const pool=branch==='first'&&SECOND_JOBS[player.job]?'firstJobPoints':'jobPoints';for(const skill of skills){player[pool]+=player.jobSkills[skill.id]||0;player.jobSkills[skill.id]=0;}const starter=skills.find(s=>s.kind!=='passive'&&s.unlock===1);if(starter&&player[pool]>0){player[pool]--;player.jobSkills[starter.id]=1;}}player.equippedJobSkill=activeJobSkills(player.job).find(s=>player.jobSkills[s.id]&&s.branch===(SECOND_JOBS[player.job]?'second':'first'))?.id||activeJobSkills(player.job)[0].id;jobSkillTimers={};classBuffs={};}
 player.hp=Math.min(player.hp,stat('hp'));player.mp=Math.min(player.mp,stat('mp'));dirty=true;if(save()===false){player=previous;return;}message('已完成重新訓練，點數已退回。','good');render();
}
function autoRevivePlayer(){
 if(player.hp>0||!player.autoRevive||!auto)return false;
 const cost=reviveCost(),oldMap=player.location;
 if(player.gold>=cost){player.gold-=cost;if(offlineMetrics){offlineMetrics.spent+=cost;offlineMetrics.revives=(offlineMetrics.revives||0)+1;}player.hp=Math.ceil(stat('hp')*.5);player.mp=Math.ceil(stat('mp')*.5);for(const pet of player.pets)if(pet.hp<=0&&gameNow()>=(pet.reviveAt||0)){pet.hp=Math.ceil(petStats(pet).hp*.5);pet.sp=Math.ceil(petStats(pet).sp*.5);}timers.respawnGrace=gameNow()+3000;player.shield=0;spawn();message(`金幣自動復活，花費 ${cost} 金。`,'good');}
 else{player.lastMap=oldMap;player.location='town';player.autoStoppedReason='gold';player.hp=Math.ceil(stat('hp')*.5);player.mp=Math.ceil(stat('mp')*.5);auto=false;spawn();message('復活金幣不足，已回城並停止掛機。','bad');}
 if(!offlineSimulation)$('reviveModal').style.display='none';dirty=true;save();return true;
}
